{
  "window_id": "w0032",
  "observed_failures": [
    {
      "filename": "034.jpg",
      "field": "date",
      "symptom": "Predicted 2018-08-09; OCR text shows 'Data: 09/08/2018' but visual inspection of the receipt shows the date is 09/03/2018. A single Tesseract pass misread the middle digit (3 glyph confused with 8).",
      "evidence": "atif_step s0006 shows pytesseract output for 034.jpg contains 'Data: 09/08/2018'; image 034.jpg clearly shows '09/03/2018'."
    },
    {
      "filename": "074.jpg",
      "field": "total_amount",
      "symptom": "Predicted 702.00; true value 102.00. OCR text includes 'Toial Amt Rounded oO yo2.00' (garbled), and the candidate picked up a '702.00' from a misread '102.00' near the keyword 'Total Amt Rounded'.",
      "evidence": "atif_step s0007 OCR output for 074.jpg shows 'Tolal Ecl. of GST 96.23\\nTotal inel. of GBT 702.00\\nToial Amt Rounded oO yo2.00'. The agent's `extract_total` takes the LAST keyword candidate's last number, which happened to be the corrupted 702.00 variant."
    },
    {
      "filename": "077.jpg",
      "field": "total_amount",
      "symptom": "Predicted 23.26; receipt shows two total lines — 'Total (Inclusive of GST): 23.26' and a final 'TOTAL: 23.25' (after a rounding adjustment of -0.01). Single-pass OCR missed the final 'TOTAL: 23.25' line entirely, so the skill could only see 23.26.",
      "evidence": "atif_step s0007 OCR output for 077.jpg ends at 'Total (Inclusive of GST): 23.26\\nRounding Ma: ~0.0)'. The 'TOTAL: 23.25' line visible in image 077.jpg is absent from the OCR."
    },
    {
      "filename": "078.jpg",
      "field": "total_amount",
      "symptom": "Predicted null/empty cell; true value 92.80. OCR produced 'GrandTota. = tS 92.80' — the 'GRAND TOTAL' keyword was mangled (missing final 'l' and no space), so the Grand-Total regex failed; fallback tiers also failed to pick up the correct line.",
      "evidence": "atif_step s0007 OCR output for 078.jpg shows 'a Total — 92:80\\nGrandTota. = tS 92.80'. Candidate pattern `\\bGRAND\\s+TOTAL\\b` cannot match 'GrandTota.'. Predictions row for 078.jpg reports total_amount as empty, feedback marks amount_correct=false."
    }
  ],
  "root_causes": [
    {
      "id": "single_pass_tesseract_only",
      "description": "The agent (and the original image-ocr SKILL as actually invoked) ran one Tesseract pass with default PSM and no preprocessing. The SKILL.md documents multi-pass / preprocessing strategies but does not require them nor describe when to escalate. On degraded receipts (034, 074, 077, 078) single-pass OCR drops or corrupts the keyword or the number, and nothing recovers it.",
      "affects": ["034.jpg date", "074.jpg amount", "077.jpg amount", "078.jpg amount"]
    },
    {
      "id": "brittle_keyword_regex",
      "description": "Priority-tier regexes use `\\b` word boundaries and exact spellings ('GRAND\\s+TOTAL', 'TOTAL\\s+AMOUNT'). OCR commonly concatenates words ('GrandTota') or chops trailing characters, so fuzzy / OCR-tolerant matching is needed in addition to strict regex.",
      "affects": ["078.jpg amount"]
    },
    {
      "id": "numeric_glyph_confusion_not_sanity_checked",
      "description": "Numbers taken from a single noisy line are accepted even when nearby clean occurrences disagree. For 074, the same amount appears correctly as 102.00 on earlier lines ('Subtotal : 102.00', 'Total incl. of GBT 702.00', 'Toial Amt Rounded oO yo2.00') but the agent returns whichever last-seen number falls under a TOTAL-tier keyword, with no cross-line consistency check. For 034, the date digit was misread with no second-source check (e.g., receipt-trailer date, time-stamp line, or 2-digit-year occurrence).",
      "affects": ["034.jpg date", "074.jpg amount"]
    },
    {
      "id": "missing_total_variant_alias_for_inclusive_gst",
      "description": "The task's priority hint places 'TOTAL' (plain) at the lowest tier, but 'Total (Inclusive of GST)' and a later 'TOTAL:' can co-occur with a small rounding delta. The skill needs explicit guidance: when multiple TOTAL-tier candidates exist, prefer the latest/largest-font 'TOTAL:' line (true grand total), not the first 'inclusive of GST' line. For 077 this didn't bite because OCR dropped the final line entirely — but the skill lacks a documented tie-break rule.",
      "affects": ["077.jpg amount"]
    },
    {
      "id": "no_escalation_when_extraction_fails",
      "description": "If `extract_total` returns None on the first OCR pass, the skill makes no attempt to retry with different preprocessing / PSM. 078 is a clear case: a second pass (e.g., upscaled + sharpened, or PSM 6 with a numeric whitelist) would very likely surface 'GRAND TOTAL' intact.",
      "affects": ["078.jpg amount"]
    }
  ],
  "skill_defects": [
    {
      "skill": "image-ocr",
      "defect": "Multi-pass OCR is described as optional with no trigger. No guidance to retry when structured-field extraction yields None, when confidence is low, or when a required keyword tier produces no match.",
      "generalizes": "All noisy / low-contrast receipt scans in similar extraction tasks."
    },
    {
      "skill": "image-ocr",
      "defect": "Structured-field regex examples use strict `\\b...\\b` boundaries and assume whitespace between words; no fuzzy/OCR-tolerant matcher is documented (e.g., allow optional internal whitespace, treat missing final 1-2 chars of a keyword as a weak match, collapse adjacent alnum into a single token).",
      "generalizes": "Any keyword-anchored extraction from Tesseract output."
    },
    {
      "skill": "image-ocr",
      "defect": "No cross-validation / consistency rule for repeated numeric values. On receipts the final total frequently appears 2–4 times; the skill should corroborate the chosen value against other occurrences and prefer a value supported by ≥2 clean reads over a lone noisy one.",
      "generalizes": "Receipts, invoices, forms with redundant fields."
    },
    {
      "skill": "image-ocr",
      "defect": "Date extraction uses a first-match-in-reading-order rule with no cross-check. Receipts typically print the transaction date twice (header and footer / timestamp line); the skill should prefer a date that appears more than once, or validate month ≤ 12 against a secondary occurrence to reduce 3↔8, 0↔6 glyph errors.",
      "generalizes": "Any date-from-scan extraction."
    },
    {
      "skill": "image-ocr",
      "defect": "Exclusion list and priority tiers do not explicitly describe how to disambiguate multiple TOTAL-tier candidates on one receipt (e.g., 'Total (Inclusive of GST)' vs a later 'TOTAL:' after rounding adjustment). Without a documented tie-break the skill silently picks the first/last candidate depending on implementation.",
      "generalizes": "Receipts with rounding-adjusted final totals."
    },
    {
      "skill": "xlsx",
      "defect": "Guidance for strict-schema outputs needs an explicit rule that `None` must be written such that a round-trip read produces an empty cell (pandas NaN / `None`), not the string `\"\"`, `\"None\"`, or `\"nan\"`. The candidate xlsx SKILL.md already contains much of this, but it should also state that `openpyxl.Workbook().append([fn, date, None])` is acceptable only if the downstream grader treats empty cells as null — otherwise prefer `pandas.to_excel` with object-dtype columns. The source run's 078.jpg row shows the ambiguity in practice.",
      "generalizes": "Any strict-schema extraction output where missing values must be null."
    },
    {
      "skill": "xlsx",
      "defect": "No checklist item requiring the writer to verify that amount strings keep two decimals AND that rows with a null amount are written as a real empty cell, before declaring the output ready.",
      "generalizes": "All line-by-line-graded spreadsheet outputs."
    }
  ],
  "repair_recommendations": [
    {
      "target_skill": "image-ocr",
      "change": "Add a 'Structured Extraction Escalation' section that mandates: (1) run a default single OCR pass with `--psm 6`; (2) if the required structured field (total, date, keyed value) is not extracted, automatically run a multi-pass pipeline over {grayscale+autocontrast, inverted, 2x upscaled, binarized at thresholds 100/128/160} × {PSM 6, 4, 11} and union the text before re-running the extractor. Document this as a required pattern, not optional."
    },
    {
      "target_skill": "image-ocr",
      "change": "Introduce an OCR-tolerant keyword matcher for structured extraction: in addition to strict `\\b...\\b` regex, document a fallback that (a) strips non-alphanumerics from the line, uppercases it, and searches for the keyword as a substring, (b) accepts the keyword if ≥80% of its characters match contiguously (e.g., 'GRANDTOTA' still matches 'GRANDTOTAL'). Provide a small helper and show it being used after the strict pass fails."
    },
    {
      "target_skill": "image-ocr",
      "change": "Document a 'numeric consistency' rule for monetary extraction: after selecting a candidate total, scan the full OCR text for all monetary-shaped numbers; if the chosen value appears exactly once but another nearby value (within ±1 edit distance after stripping decimal) appears ≥2 times on non-excluded lines, prefer the latter. Give a worked example using digits confused by Tesseract (1↔7, 0↔6, 3↔8)."
    },
    {
      "target_skill": "image-ocr",
      "change": "Expand the date-extraction section to require a cross-check: collect all date candidates across the OCR text; if a candidate's month>12 or day>31, discard it; if multiple distinct candidates survive, prefer the one with ≥2 occurrences (receipts typically print the date in both header and footer/timestamp lines). Note the common Tesseract digit confusions and add a short rule: when two otherwise-valid candidates differ only in a single digit known to be OCR-ambiguous, pick the one that co-occurs with a receipt-trailer timestamp pattern (HH:MM)."
    },
    {
      "target_skill": "image-ocr",
      "change": "Add a 'Tie-break among TOTAL-tier candidates' rule: when more than one line under the same priority tier contains a monetary value, prefer the candidate (a) that comes after any 'Rounding Adj' line, (b) whose line is labeled with a bare 'TOTAL' / 'TOTAL:' / 'GRAND TOTAL' rather than 'Total (Inclusive of GST)' / 'Total (Excluding …)' / 'Sub-total', (c) that is the last non-excluded candidate in reading order. State explicitly that 'Total (Inclusive of GST)' is a valid TOTAL-tier match but is outranked by a later bare 'TOTAL:' line on the same receipt."
    },
    {
      "target_skill": "image-ocr",
      "change": "Clarify failure semantics: every per-image extraction helper must return `None` for unresolved fields and never a sentinel string. Add a self-check bullet: 'If extraction fails for a field, the returned Python value is literally `None`, so the caller can produce a real null cell.'"
    },
    {
      "target_skill": "xlsx",
      "change": "In the Strict-Schema section, add an explicit warning about openpyxl `.append([...])` with `None` in a column: it writes an empty cell (correct) but downstream verifiers may read it as either `NaN` or empty string. Recommend the canonical pattern: build rows as dicts with `None` for missing, construct a DataFrame with explicit `columns=[...]`, cast object dtype, and write with `pandas.to_excel(..., sheet_name='...', index=False)`. Explicitly forbid writing `''`, `'None'`, `'nan'`, `float('nan')`, or pre-formatted strings for missing numeric fields."
    },
    {
      "target_skill": "xlsx",
      "change": "Add a post-write verification snippet to the Strict-Schema Contract Checklist that re-opens the file with pandas, asserts the sheet name, column list, lexicographic row order, that each non-null total matches the pattern `^\\d+\\.\\d{2}$`, and that null cells read back as `pd.isna(v)` (not as the string 'None'/'nan'). This single block would have caught the 078.jpg null-vs-empty-string ambiguity in the source run."
    },
    {
      "target_skill": "xlsx",
      "change": "Promote the task-contract bullets to a first-screen checklist: exact file path, exact single sheet name, exact column list in order, row count equals input count, sorted by filename, total_amount as two-decimal string or `None`, date as ISO `YYYY-MM-DD` or `None`. The current candidate text has these items; make them a required pre-flight checklist rather than scattered notes."
    }
  ],
  "confidence": {
    "overall": "medium-high",
    "notes": "The four failing fields are each directly traceable to the OCR text shown in the source atif_steps and the image content now supplied. Root causes attribute the failures to Tesseract noise, not to a wrong algorithmic choice by the agent, so repairs focus on hardening the extraction pipeline (multi-pass escalation, fuzzy keywords, consistency checks) rather than changing field priorities. Exact oracle values were not consulted; the amount-correct / date-correct booleans in the per-field feedback drive the diagnosis. Null-handling for 078.jpg is diagnosed from the predictions JSON showing an empty total_amount string plus feedback amount_correct=false; the underlying failure is the OCR dropping the GRAND TOTAL keyword, with the empty-cell issue as a secondary skill defect worth hardening in xlsx."
  }
}
